begin; insert into public.review_item(id,kind,severity,subject_ref,note,tenant_scope_state,detected_at) select ('13900000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,case when g%2=0 then 'content_drift' else 'fetch_failure' end,case when g%2=0 then 'warning' else 'error' end,'private-'||g,'private-note','platform_only','2026-08-27'::timestamptz+g*interval '1 second' from generate_series(1,100) g; insert into public.review_item(id,kind,severity,subject_ref,note,tenant_scope_state,resolved_at) values('13900000-0000-4000-8000-999999999999','content_drift','warning','resolved-private','resolved-private','platform_only',now()); select plan(19);
select ok(to_regprocedure('workspace_api.review_items(integer,integer)') is not null and to_regprocedure('workspace_private.review_item_is_authorized(uuid)') is not null,'tenant review functions remain installed');
select ok(to_regprocedure('workspace_private.platform_review_items(integer,integer)') is not null,'platform review interface exists');
select ok((select bool_and(r.rolname='workspace_query_owner') from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid in ('workspace_api.review_items(integer,integer)'::regprocedure,'workspace_private.review_item_is_authorized(uuid)'::regprocedure)),'tenant review functions retain the query owner');
select ok((select r.rolname='workspace_admin_owner' and p.prosecdef and p.proconfig @> array['search_path=pg_catalog, workspace_private, public, pg_temp'] from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid='workspace_private.platform_review_items(integer,integer)'::regprocedure),'platform interface has exact owner and pinned definer context');
select ok(has_function_privilege('workspace_platform_admin','workspace_private.platform_review_items(integer,integer)','EXECUTE') and not has_function_privilege('anon','workspace_private.platform_review_items(integer,integer)','EXECUTE') and not has_function_privilege('authenticated','workspace_private.platform_review_items(integer,integer)','EXECUTE') and (to_regrole('service_role') is null or not has_function_privilege('service_role','workspace_private.platform_review_items(integer,integer)','EXECUTE')),'only platform administration can execute the platform interface');
select ok((select bool_and(not has_table_privilege(role_name,'public.review_item','SELECT') and not has_table_privilege(role_name,'public.review_item_unresolved_count','SELECT') and not exists(select 1 from unnest(array['id','kind','severity','subject_ref','detected_at','resolved_at','note','created_at','tenant_scope_state']) column_name where has_column_privilege(role_name,'public.review_item',column_name,'SELECT')) and not has_column_privilege(role_name,'public.review_item_unresolved_count','unresolved_count','SELECT')) from unnest(array['anon','authenticated','service_role']) role_name where to_regrole(role_name) is not null),'client and service roles have no table or column review SELECT');
select ok((select d like '%tenant_scope_state=''platform_only''%' and d like '%resolved_atisnull%' and d like '%limitp_limitoffsetp_offset%' and d like '%category_counts%' and d like '%reason_counts%' and d like '%pagination_bound%' and d like '%octet_length(payload::text)>8192%' and d not like '%subject_ref%' and d not like '%note%' from (select regexp_replace(lower(pg_get_functiondef('workspace_private.platform_review_items(integer,integer)'::regprocedure)),'\s+','','g') d) f),'platform list is safe, bounded, grouped, and platform-only');
select ok((select d like '%authorized_section_scopes()%' and d like '%frompublic.review_item%' and d like '%resolved_atisnull%' and d like '%limitp_limitoffsetp_offset%' and d like '%octet_length(payload::text)>120000%' and d not like '%subject_ref%' and d not like '%note%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.review_items(integer,integer)'::regprocedure)),'\s+','','g') d) f),'tenant review list remains bounded and scope-authorized');
select ok((select d like '%review_item_section_scope%' and d like '%authorized_section_scopes()%' and d not like '%platform_only%' from (select regexp_replace(lower(pg_get_functiondef('workspace_private.review_item_is_authorized(uuid)'::regprocedure)),'\s+','','g') d) f),'tenant authorization predicate is unchanged');
select ok((select count(*) filter(where policyname in ('workspace_query_owner_review_select','workspace_admin_owner_platform_review_select'))=2 and count(*) filter(where policyname='workspace_query_owner_review_select' and qual like '%review_item_is_authorized%')=1 and count(*) filter(where policyname='workspace_admin_owner_platform_review_select' and qual like '%platform_only%')=1 and count(*) filter(where policyname='review_item_authenticated_read')=0 from pg_policies where schemaname='public' and tablename='review_item'),'tenant direct policy is gone while owner policies are exact');
select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.review_item_unresolved_count'::regclass),'legacy count view remains security invoker');
select ok((select indisvalid and indisready from pg_index where indexrelid='public.review_item_authorized_unresolved_idx'::regclass),'tenant ordering index remains valid');
select ok((select indisvalid and indisready and lower(pg_get_indexdef(indexrelid)) like '%tenant_scope_state = ''platform_only''::text%' from pg_index where indexrelid='public.review_item_platform_unresolved_idx'::regclass),'platform ordering index is valid and partial');
create temporary table platform_review_payload(label text primary key,payload jsonb) on commit drop; grant insert,select on platform_review_payload to workspace_platform_admin; grant workspace_platform_admin to current_user; set local role workspace_platform_admin; insert into platform_review_payload values('page',workspace_private.platform_review_items(1,0)),('full',workspace_private.platform_review_items(100,0)),('empty',workspace_private.platform_review_items(1,2000000000)); reset role;
select is((select payload->>'status' from platform_review_payload where label='page'),'ok','non-empty platform page is ok');
select is((select payload#>>'{items,0,id}' from platform_review_payload where label='page'),'13900000-0000-4000-8000-000000000100','platform page is ordered newest first');
select is((select sum((entry->>'count')::integer) from platform_review_payload cross join lateral jsonb_array_elements(payload->'category_counts') entry where label='page'),100::bigint,'category breakdown covers every unresolved platform row');
select is((select sum((entry->>'count')::integer) from platform_review_payload cross join lateral jsonb_array_elements(payload->'reason_counts') entry where label='page'),100::bigint,'reason breakdown covers every unresolved platform row');
select is((select payload->>'status' from platform_review_payload where label='full'),'payload_too_large','oversized safe projection fails closed');
select is((select payload->>'status' from platform_review_payload where label='empty'),'no_rows','an empty bounded page is distinguished from ok');
select * from finish(); rollback;
